  "output": "=== app/views/legislation/proposals/_proposal.html.erb ===
<div id="<%= dom_id(proposal) %>"
     class="proposal clear <%= ("successful" if proposal.total_votes > Proposal.votes_needed_for_success) %>"
     data-type="proposal">
  <div class="panel <%= ("with-image" if proposal.image.present?) %>">
    <% if proposal.total_votes > Proposal.votes_needed_for_success %>
      <div class="icon-successful"></div>
    <% end %>

    <% if proposal.image.present? %>
      <div class="panel-image">
        <%= image_tag proposal.image.variant(:thumb),
                      alt: proposal.image.title.unicode_normalize %>
      </div>
    <% end %>

    <%= render Shared::BasicContentComponent.new(proposal) do %>
      <%= render Shared::BasicInfoComponent.new(proposal) do %>
        <% if Geozone.any? %>
          <span class="geozone">
            <%= link_to geozone_name(proposal), legislation_process_proposals_path(proposal.legislation_process_id, search: geozone_name(proposal)) %>
          </span>
        <% end %>
      <% end %>
    <% end %>

    <div id="<%= dom_id(proposal) %>_votes">
      <%= render Legislation::Proposals::VotesComponent.new(proposal) %>
    </div>
  </div>
</div>
=== app/views/legislation/proposals/_notifications.html.erb ===
<div class="tabs-panel" id="tab-notifications">
  <div class="row">
    <div class="small-12 column">
      <% if @notifications.blank? %>
        <div class="callout primary text-center">
          <%= t("proposals.show.no_notifications") %>
        </div>
      <% end %>

      <% @notifications.each do |notification| %>
        <h3><%= notification.title %></h3>
        <p class="more-info"><%= notification.created_at.to_date %></p>
        <p><%= notification.body %></p>
      <% end %>
    </div>
  </div>
</div>
=== app/assets/stylesheets/proposals/featured_proposal.scss ===
.proposal-featured {
  min-height: $line-height * 3.5;

  .info {
    > :last-child {
      &::before {
        @include circle-separator;
      }
    }
  }

  .supports {
    @include supports;
    background: none;
    border: 0;
    padding-bottom: 0;
    padding-top: 0;

    &::after {
      content: none;
    }

    .progress,
    .total-supports {
      display: none;
    }

    .button-support {
      background: $body-font-color;
      color: $featured;
      margin-top: 0;

      &:hover {
        @extend %body-colors;
      }
    }

    .participation-not-allowed {
      background: $featured;
      padding-top: 0;

      a {
        color: inherit;
      }

      p {
        color: $color-warning;
        font-size: $small-font-size;
        line-height: $line-height;
      }
    }

    .supported {
      background: none;
      border: 0;
      font-size: $small-font-size;
      margin-bottom: 0;
      margin-top: 0;
      padding: 0;
    }
  }

  .share-supported {

    .social-share-button .ssb-icon {
      background: none;
      color: inherit;
      height: rem-calc(33);

      &::before {
        font-size: rem-calc(18);
        line-height: rem-calc(33);
      }
    }
  }
}
=== app/assets/stylesheets/proposals/featured_proposals.scss ===
.featured-proposals {
  background: $featured;
}
=== app/assets/stylesheets/proposals/form.scss ===
.proposal-form {
  @extend %public-form;
}
=== app/assets/stylesheets/proposals/geozones.scss ===
.proposals-geozones {
  a {
    @include focus-outline-on-img;
  }
}
=== app/assets/stylesheets/proposals/new.scss ===
.proposal-new {
  @extend %public-form-header;

  header h1 {
    @include has-fa-icon(lightbulb, regular, after);
  }

  aside {
    margin-top: $line-height;
  }

  .recommendations li::before {
    color: $proposals;
  }
}
=== app/assets/stylesheets/proposals/summary.scss ===
.proposals-summary {
  .panel,
  .basic-content {
    min-height: 0;
  }
}
